func run() -> String:
	var y: float = 520.0
	var zone: String = ""
	if y > 600.0:
		zone = "fondo"
	elif y > 400.0:
		zone = "basso"
	elif y > 200.0:
		zone = "centro"
	else:
		zone = "alto"
	return zone

func run() -> bool:
	var lives: int = 2
	var is_game_over: bool = false
	var can_play: bool = false
	if lives > 0 and not is_game_over:
		can_play = true
	else:
		can_play = false
	return can_play

func run() -> bool:
	var limit: float = 300.0
	var pos_y: float = 300.0
	var has_crossed: bool = false
	if pos_y > limit:
		has_crossed = true
	else:
		has_crossed = false
	return has_crossed
